import React, {useContext, useState} from 'react';
import { Container, Form, Alert } from "react-bootstrap";
import Card from "react-bootstrap/Card";
import {observer} from "mobx-react-lite";
import Button from "react-bootstrap/Button";
import { NavLink, useHistory } from 'react-router-dom';
import { LOGIN_ROUTE, REGISTRATION_ROUTE, SHOP_ROUTE } from "../utils/const";
import { useLocation } from "react-router-dom/cjs/react-router-dom";
import { login, registration } from "../http/userAPI";
import {Context} from "../index";

const Auth = () => {
    const location = useLocation()
    const history = useHistory()
    const isLogin = location.pathname === LOGIN_ROUTE
    const [email, setEmail] = useState('')
    const [password, setPassword] = useState('')
    const [error, setError] = useState('')
    const [loading, setLoading] = useState(false)
    const {user} = useContext(Context)

    const click = async () => {
        setLoading(true)
        setError('')
        
        try {
            console.log('Auth click - isLogin:', isLogin);
            console.log('Email:', email);
            
            let data;
            if (isLogin) {
                data = await login(email, password);
            } else {
                data = await registration(email, password);
            }
            
            console.log('Auth success - user data:', data);
            
            // Устанавливаем пользователя с данными из токена
            user.setUser({
                id: data.id,
                email: data.email,
                role: data.role
            }); 
            user.setIsAuth(true);
            
            console.log('User after auth:', user.user);
            console.log('Is auth:', user.isAuth);
            
            history.push(SHOP_ROUTE);
        } catch (e) {
            console.error('Auth error:', e);
            const errorMessage = e.response?.data?.message || 'Произошла ошибка при авторизации';
            setError(errorMessage);
            alert(errorMessage);
        } finally {
            setLoading(false);
        }
    }

    return (
        <Container
            className="d-flex justify-content-center align-items-center"
            style={{ height: window.innerHeight - 54 }}
        >
            <Card style={{ width: 668 }} className="p-5">
                <h2 className="m-auto">{isLogin ? "Авторизация" : "Регистрация"}</h2>
                
                {error && (
                    <Alert variant="danger" className="mt-3">
                        {error}
                    </Alert>
                )}
                
                <Form className="d-flex flex-column">
                    <Form.Control
                        className="mt-3"
                        placeholder="Введите ваш email..."
                        value={email}
                        onChange={e => setEmail(e.target.value)}
                        type="email"
                    />
                    <Form.Control
                        className="mt-3"
                        placeholder="Введите ваш пароль..."
                        value={password}
                        onChange={e => setPassword(e.target.value)}
                        type="password"
                    />
                    <div className="d-flex flex-column">
                        {isLogin ? 
                            <div className="mt-3">
                                Нет аккаунта? <NavLink to={REGISTRATION_ROUTE}>Зарегистрируйся!</NavLink>
                            </div>
                            :
                            <div className="mt-3">
                                Есть аккаунт? <NavLink to={LOGIN_ROUTE}>Войдите!</NavLink>
                            </div>
                        }
                        <Button
                            className="mt-3 align-self-end"
                            variant="outline-success"
                            onClick={click}
                            disabled={loading || !email || !password}
                        >
                            {loading ? 'Загрузка...' : (isLogin ? "Войти" : "Регистрация")}  
                        </Button>
                    </div>
                </Form>
            </Card>
        </Container>
    );
};

export default observer(Auth);
